121	func resolveXDGDir(pluginDir, pluginEnv, xdgEnv, homeFallback string) (string, error) {
122		if pluginDir != "" {
123			if !filepath.IsAbs(pluginDir) {
124				return "", fmt.Errorf("%s must be absolute, got %q", pluginEnv, pluginDir)
125			}
126			return pluginDir, nil
127		}
128		if xdg := os.Getenv(xdgEnv); xdg != "" {
129			if filepath.IsAbs(xdg) {
130				return filepath.Join(xdg, xdgRootDir), nil
131			}
132			// XDG says relative paths are invalid; ignore and fall back to HOME.
133		}
134		home, err := os.UserHomeDir()
135		if err != nil {
136			return "", fmt.Errorf("resolve home dir: %w", err)
137		}
138		return filepath.Join(home, homeFallback), nil
139	}
