149	// localRepoIdentityConflictError refuses to guess when an upgrade finds state
150	// under both the canonical root identity and the exact pre-upgrade lexical
151	// alias identity. Choosing either would hide the other repository history.
152	type localRepoIdentityConflictError struct {
153		Canonical repoStorage
154		Legacy    repoStorage
155	}
156	
157	// Error names the command that resolves the conflict.
158	//
159	// It used to end with "move one brain/head store aside and retry" -- a manual
160	// filesystem instruction with nothing behind it. Since every repo-scoped
161	// command refuses while the conflict stands, and that includes the deletes a
162	// reader would reach for, the message was the ONLY thing standing between the
163	// user and a dead repository, and it pointed at `mv`. Naming a command that
164	// exists is the difference between a diagnosis and a recovery path.
165	func (e *localRepoIdentityConflictError) Error() string {
166		return fmt.Sprintf(
167			"%s: state exists for canonical local repo key %q and pre-upgrade alias key %q; "+
168				"run `%s repo-identity` to see both stores, then `%s repo-identity --keep <repo-key>` "+
169				"to keep one and move the other aside (canonical brain: %s; legacy brain: %s)",
170			localRepoIdentityConflictCode,
171			e.Canonical.Key,
172			e.Legacy.Key,
173			setupCommandPrefix(os.LookupEnv),
174			setupCommandPrefix(os.LookupEnv),
175			e.Canonical.BrainDir,
176			e.Legacy.BrainDir,
177		)
178	}
