180	type repoStorageIdentity struct {
181		// Key is the identity every spelling of the same repository root must
182		// agree on: the root with EVERY path component resolved through symlinks.
183		//
184		// It used to be the caller's lexical spelling, which made the key a
185		// property of HOW the repository was addressed rather than of WHICH
186		// repository it is. A relative invocation from inside the working tree can
187		// only ever produce the physical spelling (git and the getcwd syscall both
188		// report it), while an absolute ENTIRE_REPO_ROOT keeps whatever the caller
189		// typed -- so on any host where a repository is reachable through a
190		// symlinked ancestor (macOS /tmp -> /private/tmp being the everyday case)
191		// the two routes minted two keys, built two brains, and then refused every
192		// command with a repo_identity_conflict once both existed. Only the fully
193		// resolved root is the same string no matter which route asked.
194		Key string
195	
196		// AlternateKeys are the other spellings of this same root that an earlier
197		// build may already have keyed this repository's brain under: the lexical
198		// spelling the caller supplied, and the spelling with only the root's final
199		// component resolved (the pre-fix canonical form). They are not separate
200		// repositories -- they are the same directory under a different name -- so
201		// an existing brain found under one of them is adopted in place rather than
202		// orphaned, and state under more than one is reported rather than guessed.
203		AlternateKeys []string
204	
205		Local bool
206	}
