208	// repoStorageSet is every store one repository could be using: the canonical
209	// one its identity names, and every spelling of that same root that currently
210	// holds state.
211	//
212	// It exists so the repair paths -- the ones whose whole job is to clear a
213	// duplicate store -- can see the duplicate instead of being refused by it.
214	// repoStoragePaths, which every ordinary command uses, turns the same facts
215	// into the single store to read and write, or into the refusal.
216	type repoStorageSet struct {
217		// Canonical is the store this repository's identity names, whether or not
218		// anything has been written there yet.
219		Canonical repoStorage
220		// Populated is every store holding state, canonical first when it holds
221		// any. More than one entry is the identity conflict.
222		Populated []repoStorage
223		// Local reports whether the identity came from the repository root's path
224		// (as opposed to a remote), which is the only case that can have
225		// alternates at all.
226		Local bool
227	}
228	
229	// Conflicted reports whether this repository's brain is split across more than
230	// one store.
231	func (s repoStorageSet) Conflicted() bool { return len(s.Populated) > 1 }
232	
233	// Active is the store ordinary commands read and write: the one established
234	// store when exactly one spelling holds state (adopted in place, so no files
235	// move), otherwise the canonical one.
236	func (s repoStorageSet) Active() repoStorage {
237		if len(s.Populated) == 1 {
238			return s.Populated[0]
239		}
240		return s.Canonical
241	}
