243	// conflictError renders the split as the refusal ordinary commands report.
244	func (s repoStorageSet) conflictError() error {
245		if !s.Conflicted() {
246			return nil
247		}
248		return &localRepoIdentityConflictError{Canonical: s.Populated[0], Legacy: s.Populated[1]}
249	}
