255	func resolveRepoStorageSetWithSlug(ctx context.Context, runner CommandRunner, env EntireEnv, repoDir string, slugForHost func(string, string) (string, error)) (repoStorageSet, error) {
256		dirs, err := resolvePluginDirs(env)
257		if err != nil {
258			return repoStorageSet{}, err
259		}
260		identity, err := resolveRepoStorageIdentityWithSlug(ctx, runner, dirs.Config, repoDir, repoDir, slugForHost)
261		if err != nil {
262			return repoStorageSet{}, err
263		}
264		brainRoot := filepath.Join(dirs.Data, repoStoreDirName)
265		canonical := repoStorageForKey(dirs, identity.Key)
266		if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(canonical.Key)); err != nil {
267			return repoStorageSet{}, err
268		}
269		set := repoStorageSet{Canonical: canonical, Local: identity.Local}
270		if !identity.Local {
271			return set, nil
272		}
273		canonicalExists, err := repoStorageContainsState(canonical)
274		if err != nil {
275			return repoStorageSet{}, err
276		}
277		if canonicalExists {
278			set.Populated = append(set.Populated, canonical)
279		}
280		for _, key := range identity.AlternateKeys {
281			alternate := repoStorageForKey(dirs, key)
282			if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(alternate.Key)); err != nil {
283				return repoStorageSet{}, err
284			}
285			exists, err := repoStorageContainsState(alternate)
286			if err != nil {
287				return repoStorageSet{}, err
288			}
289			if exists {
290				set.Populated = append(set.Populated, alternate)
291			}
292		}
293		return set, nil
294	}
