402	func resolveRepoStorageIdentityWithSlug(ctx context.Context, runner CommandRunner, configDir, repoDir, legacyRepoDir string, slugForHost func(string, string) (string, error)) (repoStorageIdentity, error) {
403		legacyRepoDir = filepath.Clean(legacyRepoDir)
404		rootLinkResolved, err := rootSymlinkResolvedLocalRepoDir(repoDir)
405		if err != nil {
406			return repoStorageIdentity{}, err
407		}
408		if runner != nil {
409			stdout, _, err := runner.Run(ctx, rootLinkResolved, "git", "remote", "get-url", "origin")
410			if err == nil {
411				if key, ok, keyErr := repoKeyFromRemoteWithSlug(configDir, strings.TrimSpace(string(stdout)), slugForHost); ok || keyErr != nil {
412					return repoStorageIdentity{Key: key}, keyErr
413				}
414			}
415		}
416		canonicalKey, err := localRepoStorageKey(rootLinkResolved)
417		if err != nil {
418			return repoStorageIdentity{}, err
419		}
420		identity := repoStorageIdentity{Key: canonicalKey, Local: true}
421		// The spellings this same root used to be keyed under, newest rule first:
422		// the final-component-resolved form (the pre-fix canonical), then the raw
423		// lexical form the caller supplied. Either may already hold the brain.
424		for _, spelling := range []string{rootLinkResolved, legacyRepoDir} {
425			key := localRepoStorageKeyForSpelling(spelling)
426			if key == identity.Key || slices.Contains(identity.AlternateKeys, key) {
427				continue
428			}
429			identity.AlternateKeys = append(identity.AlternateKeys, key)
430		}
431		return identity, nil
432	}
