434	// localRepoStorageKey is the ONE derivation of a local repository's storage key,
435	// and the only one any caller should use: the repository root with every path
436	// component resolved through symlinks, hashed.
437	//
438	// Full resolution is what makes the key a property of the repository rather
439	// than of the route taken to it. Every other spelling -- an absolute
440	// ENTIRE_REPO_ROOT through a symlinked ancestor, a `cd` through an alias, a
441	// relative invocation -- collapses onto this one, so a repository cannot end up
442	// with two brains and then be locked out of both.
443	//
444	// The deliberate error path: EvalSymlinks fails on a path that does not exist
445	// yet, and workspace manifests carry exactly such paths as durable hints for
446	// checkouts that are not present. A missing root therefore keeps its lexical
447	// spelling and no error. Any OTHER failure -- a resolution loop, an unreadable
448	// ancestor, a network mount that is up enough to stat but not to walk -- is
449	// REPORTED rather than silently degraded to the lexical spelling: degrading
450	// would mint exactly the second key this function exists to prevent, and the
451	// brain the repository already has would be invisible until the mount came
452	// back, at which point both would exist and every command would refuse.
453	func localRepoStorageKey(repoDir string) (string, error) {
454		root, err := canonicalLocalRepoRoot(repoDir)
455		if err != nil {
456			return "", err
457		}
458		return localRepoStorageKeyForSpelling(root), nil
459	}
460	
461	// localRepoStorageKeyForSpelling hashes the spelling it is handed, verbatim.
462	// It is for ALTERNATE identities only -- the historical spellings a brain may
463	// already be stored under. Deriving the identity of a repository with it is the
464	// defect; use localRepoStorageKey.
465	func localRepoStorageKeyForSpelling(repoDir string) string {
466		return filepath.ToSlash(filepath.Join("local", localRepoKey(repoDir)))
467	}
