469	// canonicalLocalRepoRoot resolves every component of a repository root. See
470	// localRepoStorageKey for why, and for the error contract.
471	func canonicalLocalRepoRoot(repoDir string) (string, error) {
472		if repoDir == "" {
473			return "", nil
474		}
475		cleaned := filepath.Clean(repoDir)
476		resolved, err := filepath.EvalSymlinks(cleaned)
477		switch {
478		case err == nil:
479			return filepath.Clean(resolved), nil
480		case errors.Is(err, os.ErrNotExist):
481			// A root that is not here yet is a durable hint, not an identity to
482			// refuse; keep the caller's spelling so the hint still resolves to the
483			// same key when the checkout appears.
484			return cleaned, nil
485		default:
486			return "", fmt.Errorf("resolve local repo root %s: %w", cleaned, err)
487		}
488	}
489	
490	// rootSymlinkResolvedLocalRepoDir resolves only a symlink in the repository
491	// root's FINAL path component.
492	//
493	// This was the canonical identity until full resolution replaced it, and it is
494	// kept for exactly two jobs. It is the directory git is invoked in, so a
495	// repository addressed through an alias is interrogated at its target. And it
496	// is one of the alternate key spellings a brain may already be stored under --
497	// see repoStorageIdentity.AlternateKeys -- which is why the rule it implements
498	// must not drift: an old store is only found again if this reproduces the
499	// spelling that created it.
500	//
501	// Missing paths remain untouched because workspace manifests use them as
502	// durable hints that may become available again later. Broken final-component
503	// links likewise retain the original hint until their targets exist.
504	func rootSymlinkResolvedLocalRepoDir(repoDir string) (string, error) {
505		if repoDir == "" {
506			return "", nil
507		}
508		original := filepath.Clean(repoDir)
509		current := original
510		const maxRootSymlinkDepth = 40
511		seen := make(map[string]struct{}, 1)
512		for depth := 0; depth < maxRootSymlinkDepth; depth++ {
513			if _, ok := seen[current]; ok {
514				return "", fmt.Errorf("resolve local repo root symlinks: cycle at %q", current)
515			}
516			seen[current] = struct{}{}
517	
518			info, err := os.Lstat(current)
519			if err == nil && info.Mode()&os.ModeSymlink == 0 {
520				return current, nil
521			}
522			if errors.Is(err, os.ErrNotExist) {
523				return original, nil
524			}
525			if err != nil {
526				return "", fmt.Errorf("stat local repo root: %w", err)
527			}
528	
529			target, err := os.Readlink(current)
530			if err != nil {
531				return "", fmt.Errorf("read local repo root symlink: %w", err)
532			}
533			if !filepath.IsAbs(target) {
534				target = filepath.Join(filepath.Dir(current), target)
535			}
536			current = filepath.Clean(target)
537		}
538		return "", fmt.Errorf("resolve local repo root symlinks: exceeded %d links", maxRootSymlinkDepth)
539	}
