545	func repoKeyFromRemoteWithSlug(configDir, remote string, slugForHost func(string, string) (string, error)) (string, bool, error) {
546		remote = strings.TrimSpace(remote)
547		if parsed, err := url.Parse(remote); err == nil && strings.EqualFold(parsed.Scheme, "entire") {
548			if parsed.Hostname() == "" {
549				return "", false, nil
550			}
551			components := normalizeRepoPath(parsed.Path)
552			if len(components) < 3 {
553				return "", false, nil
554			}
555			key := strings.Join(components, "/")
556			if components[0] == workspaceDirName {
557				return "", true, fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
558			}
559			return key, true, nil
560		}
561	
562		host, repoPath, ok := parseRepoRemote(remote)
563		if !ok {
564			return "", false, nil
565		}
566		slug, err := slugForHost(configDir, host)
